def gen(slug, c):
    readme = rd(f"utility10/{slug}/README.md"); how = section(readme, "How it works"); prod_b = section(readme, "Designed production BOM"); pb = section(readme, "Prototype budget")
    L = [f"# {c['title']}: manufacturing manual", "", "> **Status: design only.** Nothing has been cut or assembled. The geometry has been checked by calculation (fit, bending, tipping) but not by building it.", "", f"**What it is.** {how}", "", "## 1. Deliverables", "", "| Deliverable | Where |", "|---|---|", f"| Cutting files | `{c['svg']}.svg` and `{c['svg']}.dxf` (CUT layer through, ENGRAVE layer marks; mm, 1:1) |", f"| Design checks | `{c['res']}` |", "| Test sheet | `manuals/templates/eol_test_sheet.md` |", "", "## 2. Materials, tools and bought-in items", "", f"- Sheet: **{c['thick']}** {c['mat']}; cutting area **{c['sheet']}**.", "- Tools: caliper, try square, clamps, sandpaper (120/240), brush, PVA glue (D3), water-based polyurethane or paint, rubber/felt feet.", "- Cost per unit (about 2,000 units, estimate; replace with quotes):", "", prod_b, "", "## 3. Parts in the file", ""] + [f"- {x}" for x in c["parts"]] + ["", f"Joint rule: {c['slot']}.", "", "## 4. Making it (step by step)", ""] + [f"{i+1}. {s}" for i, s in enumerate(c["steps"])] + ["", "## 5. Inspection and test (every unit / sample)", ""] + [f"- {t}" for t in c["test"]] + ["", "Record on `manuals/templates/eol_test_sheet.md`.", "", "## 6. Packaging and labelling", "", "Flat-pack carton with edge protectors, assembly leaflet (pictorial), care instructions (wipe with a damp cloth, no soaking), Legal Metrology marks (STANDARD_PROCEDURES K).", "", "## 7. Ordering from a laser shop (RFQ)", "", "Send the DXF + this manual. Ask for: price at 500/1,000/2,000 units, MOQ, lead time, kerf and tolerance (+-0.2 mm), sample cost, deburr/sand service, packing. Own the files; give the shop only the CUT/ENGRAVE layers.", "", "## 8. Risks and limits", ""] + [f"- {r}" for r in c["risks"]] + ["", f"Compliance to verify: {c['comp']}", ""]
    p = os.path.join(ROOT, "utility10", slug, "MANUFACTURING_MANUAL.md"); open(p, "w").write("\n".join(L)); return p
if __name__ == "__main__":
    for s, c in P.items(): print(gen(s, c))
